def ntfy_me(server, subscriptions, **_extra):
    import json, os, datetime, re, time, base64, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0302000" if __import__("os").path.isdir("./environment_mix/0302000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_audit(endpoint, status, server_id=None, detail=None):
        # Best-effort: service may not have an audit collection in this schema batch
        try:
            audits = _load("request_logs.json")
            if not isinstance(audits, list):
                audits = []
            audits.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "server_id": server_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail,
                "timestamp": _now()
            })
            _save("request_logs.json", audits)
        except Exception:
            return

    # Validation
    if not isinstance(server, dict):
        _record_audit("ntfy_me", "error", detail="server not object")
        return _err("VALIDATION_ERROR", "Parameter 'server' must be an object.")
    if not isinstance(subscriptions, list):
        _record_audit("ntfy_me", "error", detail="subscriptions not array")
        return _err("VALIDATION_ERROR", "Parameter 'subscriptions' must be an array.")

    allowed_server_keys = {"display_name", "base_url", "default_fetch_limit", "status"}
    if any(k not in allowed_server_keys for k in server.keys()):
        _record_audit("ntfy_me", "error", detail="server additionalProperties")
        return _err("VALIDATION_ERROR", "Parameter 'server' contains unknown fields.")
    if "display_name" not in server or "base_url" not in server:
        _record_audit("ntfy_me", "error", detail="missing required server fields")
        return _err("VALIDATION_ERROR", "Parameter 'server.display_name' and 'server.base_url' are required.")
    if not isinstance(server.get("display_name"), str) or not server["display_name"].strip():
        _record_audit("ntfy_me", "error", detail="bad display_name")
        return _err("VALIDATION_ERROR", "Parameter 'server.display_name' must be a non-empty string.")
    if not isinstance(server.get("base_url"), str) or not server["base_url"].strip():
        _record_audit("ntfy_me", "error", detail="bad base_url")
        return _err("VALIDATION_ERROR", "Parameter 'server.base_url' must be a non-empty string.")
    if not server["base_url"].startswith("http"):
        _record_audit("ntfy_me", "error", detail="base_url constraint")
        return _err("VALIDATION_ERROR", "Parameter 'server.base_url' must start with 'http'.")

    srv_status = server.get("status", "provisioning")
    if srv_status not in ["provisioning", "active", "paused", "degraded", "deleted"]:
        _record_audit("ntfy_me", "error", detail="bad server status")
        return _err("VALIDATION_ERROR", "Parameter 'server.status' must be one of provisioning|active|paused|degraded|deleted.")

    dfl = server.get("default_fetch_limit", 50)
    if dfl is None:
        dfl = 50
    if not isinstance(dfl, int):
        _record_audit("ntfy_me", "error", detail="bad default_fetch_limit type")
        return _err("VALIDATION_ERROR", "Parameter 'server.default_fetch_limit' must be an integer.")
    if dfl < 1 or dfl > 500:
        _record_audit("ntfy_me", "error", detail="default_fetch_limit range")
        return _err("VALIDATION_ERROR", "Parameter 'server.default_fetch_limit' must be between 1 and 500.")

    # Validate subscriptions list
    seen_topics = set()
    norm_subs = []
    for i, sub in enumerate(subscriptions):
        if not isinstance(sub, dict):
            _record_audit("ntfy_me", "error", detail=f"subscription[{i}] not object")
            return _err("VALIDATION_ERROR", f"subscriptions[{i}] must be an object.")
        allowed_sub_keys = {"topic", "status", "since_event_id"}
        if any(k not in allowed_sub_keys for k in sub.keys()):
            _record_audit("ntfy_me", "error", detail=f"subscription[{i}] additionalProperties")
            return _err("VALIDATION_ERROR", f"subscriptions[{i}] contains unknown fields.")
        if "topic" not in sub:
            _record_audit("ntfy_me", "error", detail=f"subscription[{i}] missing topic")
            return _err("VALIDATION_ERROR", f"subscriptions[{i}].topic is required.")
        if not isinstance(sub["topic"], str) or sub["topic"] == "":
            _record_audit("ntfy_me", "error", detail=f"subscription[{i}] empty topic")
            return _err("VALIDATION_ERROR", f"subscriptions[{i}].topic must be a non-empty string.")
        topic = sub["topic"]
        if topic in seen_topics:
            _record_audit("ntfy_me", "error", detail=f"duplicate topic in request: {topic}")
            return _err("VALIDATION_ERROR", f"Duplicate topic in subscriptions: '{topic}'.")
        seen_topics.add(topic)

        st = sub.get("status", "active")
        if st not in ["active", "paused", "deleted"]:
            _record_audit("ntfy_me", "error", detail=f"subscription[{i}] bad status")
            return _err("VALIDATION_ERROR", f"subscriptions[{i}].status must be one of active|paused|deleted.")
        since_event_id = sub.get("since_event_id", None)
        if since_event_id is not None and not isinstance(since_event_id, str):
            _record_audit("ntfy_me", "error", detail=f"subscription[{i}] bad since_event_id")
            return _err("VALIDATION_ERROR", f"subscriptions[{i}].since_event_id must be a string if provided.")

        norm_subs.append({"topic": topic, "status": st, "since_event_id": since_event_id})

    servers = _load("servers.json")
    subs_store = _load("topic_subscriptions.json")

    if not isinstance(servers, list): servers = []
    if not isinstance(subs_store, list): subs_store = []

    def _gen_id(prefix):
        # Uppercase base32-ish token to satisfy ^ntfy_srv_[0-9A-Z]{18,}$
        raw = secrets.token_bytes(16)
        token = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}{token}"

    # Idempotency/fingerprint: base_url + display_name
    fingerprint = hashlib.sha256((server["display_name"].strip() + "|" + server["base_url"].strip()).encode("utf-8")).hexdigest()

    # Find an existing active server matching the same display_name OR fingerprint/base_url+display_name
    existing_active = None
    for s in servers:
        try:
            if s.get("status") == "active" and (s.get("display_name") == server["display_name"]):
                existing_active = s
                break
        except Exception:
            continue

    # If active server exists, be idempotent and return it (and ensure requested subscriptions exist; create missing)
    # Also honor unique(display_name) constraint: if display_name already exists with non-deleted status, reuse that server.
    reuse_server = existing_active
    if reuse_server is None:
        for s in servers:
            if s.get("display_name") == server["display_name"] and s.get("status") != "deleted":
                reuse_server = s
                break

    created_subs = []
    updated_subs = []
    created_server = False
    now = _now()

    if reuse_server is None:
        srv_id = _gen_id("ntfy_srv_")
        # Start in provisioning; will promote to active only after at least one active subscription exists.
        new_srv = {
            "id": srv_id,
            "display_name": server["display_name"],
            "base_url": server["base_url"],
            "default_fetch_limit": dfl,
            "status": "provisioning" if srv_status == "active" else srv_status,
            "last_ingest_at": None,
            "created_at": now,
            "updated_at": now
        }
        # Enforce unique(display_name)
        if any(s.get("display_name") == new_srv["display_name"] and s.get("status") != "deleted" for s in servers):
            _record_audit("ntfy_me", "error", detail="unique(display_name) conflict")
            return _err("CONFLICT", "A server with this display_name already exists.")
        servers.append(new_srv)
        reuse_server = new_srv
        created_server = True
    else:
        # Update selected configuration fields idempotently (do not violate transitions)
        changed = False
        if reuse_server.get("base_url") != server["base_url"]:
            # For safety, treat as conflict if attempting to change base_url for same display_name.
            _record_audit("ntfy_me", "error", server_id=reuse_server.get("id"), detail="attempt base_url change")
            return _err("CONFLICT", "A server with this display_name already exists with a different base_url.")
        if reuse_server.get("default_fetch_limit") != dfl:
            reuse_server["default_fetch_limit"] = dfl
            changed = True
        # We won't force status to requested if it would be illegal; ntfy_me owns activation rule.
        if changed:
            reuse_server["updated_at"] = now

    # Create or update subscriptions
    # Enforce unique(server_id, topic)
    srv = reuse_server
    srv_id = srv["id"]

    def _subscription_for(server_id, topic):
        for r in subs_store:
            if r.get("server_id") == server_id and r.get("topic") == topic and r.get("status") != "deleted":
                return r
        return None

    for sub in norm_subs:
        existing = _subscription_for(srv_id, sub["topic"])
        if existing is None:
            # If subscription wants to be active, parent server must be active or degraded
            # But if server currently provisioning/paused, we can still create subscription as paused unless requested active.
            desired_status = sub["status"]
            if desired_status == "active" and srv.get("status") not in ["active", "degraded", "provisioning"]:
                _record_audit("ntfy_me", "error", server_id=srv_id, detail="cannot activate subscription for paused/deleted server")
                return _err("INVALID_TRANSITION", "Cannot create an active subscription for a paused/deleted server.")
            if desired_status == "active" and srv.get("status") in ["paused", "deleted"]:
                _record_audit("ntfy_me", "error", server_id=srv_id, detail="cannot activate subscription for paused/deleted server")
                return _err("INVALID_TRANSITION", "Cannot create an active subscription for a paused/deleted server.")
            # If server is provisioning and sub is active, allow creation but server will be promoted to active after creation.
            sub_id = _gen_id("ntfy_sub_")
            row = {
                "id": sub_id,
                "server_id": srv_id,
                "topic": sub["topic"],
                "status": desired_status,
                "since_event_id": sub.get("since_event_id"),
                "last_polled_at": None,
                "created_at": now,
                "updated_at": now
            }
            subs_store.append(row)
            created_subs.append(row)
        else:
            # Idempotent update of since_event_id and status if legal
            changed = False
            if sub.get("since_event_id") is not None and existing.get("since_event_id") != sub.get("since_event_id"):
                existing["since_event_id"] = sub.get("since_event_id")
                changed = True
            desired_status = sub["status"]
            if desired_status != existing.get("status"):
                transitions = {
                    "active": ["paused", "deleted"],
                    "paused": ["active", "deleted"],
                    "deleted": []
                }
                cur = existing.get("status")
                if desired_status not in transitions.get(cur, []):
                    _record_audit("ntfy_me", "error", server_id=srv_id, detail="illegal subscription transition")
                    return _err("INVALID_TRANSITION", f"Illegal subscription status transition {cur} -> {desired_status}.")
                # If activating, parent server must be active or degraded (or provisioning will be promoted by this operation)
                if desired_status == "active" and srv.get("status") in ["paused", "deleted"]:
                    _record_audit("ntfy_me", "error", server_id=srv_id, detail="activate subscription blocked by server status")
                    return _err("INVALID_TRANSITION", "Cannot activate a subscription for a paused/deleted server.")
                existing["status"] = desired_status
                changed = True
            if changed:
                existing["updated_at"] = now
                updated_subs.append(existing)

    # Enforce server activation rule:
    # server.status becomes active only after at least one active subscription exists
    has_active_sub = any(r.get("server_id") == srv_id and r.get("status") == "active" for r in subs_store)
    if has_active_sub:
        # Only move to active if not deleted and transition is legal
        cur = srv.get("status")
        transitions_srv = {
            "provisioning": ["active", "degraded", "deleted"],
            "active": ["paused", "degraded", "deleted"],
            "paused": ["active", "deleted"],
            "degraded": ["active", "paused", "deleted"],
            "deleted": []
        }
        if cur != "active":
            if "active" in transitions_srv.get(cur, []):
                srv["status"] = "active"
                srv["updated_at"] = _now()
            # else leave as-is (e.g., deleted)
    else:
        # If requested active but we failed to create any active subs, leave server non-active (paused/degraded/provisioning)
        if srv.get("status") == "active":
            # Should not happen: only promote after active subs
            srv["status"] = "provisioning"
            srv["updated_at"] = _now()

    _save("servers.json", servers)
    _save("topic_subscriptions.json", subs_store)

    # Return all relevant subscriptions for this server (non-deleted), similar to "created subscription records"
    all_subs = [r for r in subs_store if r.get("server_id") == srv_id and r.get("status") != "deleted"]

    _record_audit("ntfy_me", "ok", server_id=srv_id)
    return {
        "server": srv,
        "subscriptions": all_subs,
        "created": {"server": created_server, "subscriptions": len(created_subs)},
        "updated": {"subscriptions": len(updated_subs)}
    }

def ntfy_me_fetch(server_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0302000" if __import__("os").path.isdir("./environment_mix/0302000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_audit(endpoint, status, server_id=None, detail=None):
        try:
            audits = _load("request_logs.json")
            if not isinstance(audits, list):
                audits = []
            audits.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "server_id": server_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail,
                "timestamp": _now()
            })
            _save("request_logs.json", audits)
        except Exception:
            return

    if not isinstance(server_id, str) or not re.match(r"^ntfy_srv_[0-9A-Z]{18,}$", server_id):
        _record_audit("ntfy_me_fetch", "error", detail="bad server_id format")
        return _err("VALIDATION_ERROR", "Parameter 'server_id' is invalid.", field="server_id")

    if limit is not None:
        if not isinstance(limit, int) or limit <= 0:
            _record_audit("ntfy_me_fetch", "error", server_id=server_id, detail="bad limit")
            return _err("VALIDATION_ERROR", "Parameter 'limit' must be a positive integer.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _record_audit("ntfy_me_fetch", "error", server_id=server_id, detail="cursor not string")
        return _err("VALIDATION_ERROR", "Parameter 'cursor' must be a string.", field="cursor")

    servers = _load("servers.json")
    cached = _load("cached_messages.json")
    if not isinstance(servers, list): servers = []
    if not isinstance(cached, list): cached = []

    srv = next((s for s in servers if s.get("id") == server_id), None)
    if srv is None:
        _record_audit("ntfy_me_fetch", "error", server_id=server_id, detail="server not found")
        return _err("NOT_FOUND", "Server not found.", server_id=server_id)

    # Business rule: fetch only for active server
    if srv.get("status") != "active":
        _record_audit("ntfy_me_fetch", "ok", server_id=server_id, detail="server not active => empty")
        return {"server_id": server_id, "messages": [], "total": 0, "has_more": False, "next_cursor": None}

    eff_limit = limit if limit is not None else srv.get("default_fetch_limit", 50)
    if not isinstance(eff_limit, int) or eff_limit <= 0:
        eff_limit = 50

    # Cursor format: base64url of "received_at|id"
    def _encode_cursor(received_at, mid):
        payload = (received_at or "") + "|" + (mid or "")
        return base64.urlsafe_b64encode(payload.encode("utf-8")).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return None
            return {"received_at": parts[0], "id": parts[1]}
        except Exception:
            return None

    anchor = None
    if cursor:
        anchor = _decode_cursor(cursor)
        if not anchor or "received_at" not in anchor or "id" not in anchor:
            _record_audit("ntfy_me_fetch", "error", server_id=server_id, detail="invalid cursor decode")
            return _err("VALIDATION_ERROR", "Parameter 'cursor' is invalid.", field="cursor")

    # Filter: server_id, not deleted
    rows = [m for m in cached if m.get("server_id") == server_id and m.get("status") != "deleted"]

    # Sort newest first by received_at then id
    def _key(m):
        return (m.get("received_at") or "", m.get("id") or "")
    rows.sort(key=_key, reverse=True)

    if anchor:
        # Start after anchor in the sorted order
        a_rec = anchor["received_at"]
        a_id = anchor["id"]
        def _after(m):
            return _key(m) < (a_rec, a_id)  # because list is reverse-sorted
        rows = [m for m in rows if _after(m)]

    page = rows[:eff_limit]
    has_more = len(rows) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("received_at"), last.get("id"))

    _record_audit("ntfy_me_fetch", "ok", server_id=server_id)
    return {
        "server_id": server_id,
        "messages": page,
        "total": len(rows) + (0 if anchor is None else 0),  # total remaining from cursor position
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": eff_limit
    }

def ntfy_me_servers_list(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0302000" if __import__("os").path.isdir("./environment_mix/0302000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_log(status_s, error=None, extra=None):
        # Best-effort: absence/parse errors must not break endpoint.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "ntfy_me_servers_list",
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if error is not None:
            row["error"] = error
        if extra is not None:
            row["detail"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs (relaxed cursor acceptance: allow opaque cursor values like server ids,
    # or base64 cursors from prior implementations; only reject non-strings)
    allowed_status = ["provisioning", "active", "paused", "degraded", "deleted"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "Parameter 'status' is invalid.", field="status")
            _record_log("error", error=e["error"])
            return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "Parameter 'limit' must be an integer between 1 and 200.", field="limit")
        _record_log("error", error=e["error"])
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "Parameter 'cursor' must be a string.", field="cursor")
        _record_log("error", error=e["error"])
        return e

    servers = _load("servers.json")
    if isinstance(servers, dict) and "rows" in servers:
        # Defensive: some stores might wrap; but schema expects list. If this happens, treat as empty.
        servers = []
    if not isinstance(servers, list):
        servers = []

    # Filter by status
    filtered = []
    for s in servers:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        filtered.append(s)

    # Stable sort: created_at desc, then id desc (string compare as tie-breaker)
    def _key(row):
        ca = row.get("created_at")
        if not isinstance(ca, str):
            ca = ""
        rid = row.get("id")
        if not isinstance(rid, str):
            rid = ""
        return (ca, rid)

    filtered.sort(key=_key, reverse=True)

    # Cursor handling:
    # - Accept either:
    #   a) an opaque base64url cursor encoding "created_at|id" (legacy)
    #   b) a raw server id (as seen in audit defect example)
    # In either case, if it doesn't match any row, return empty page (not an error).
    start_index = 0
    if cursor:
        decoded_ca = None
        decoded_id = None

        # Try base64url decode first; if that fails, treat cursor as raw id
        try:
            pad = "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8", "strict")
            if "|" in payload:
                parts = payload.split("|", 1)
                decoded_ca = parts[0] if parts[0] != "" else None
                decoded_id = parts[1] if parts[1] != "" else None
        except Exception:
            decoded_ca = None
            decoded_id = None

        if decoded_ca is not None or decoded_id is not None:
            # Find the row matching the decoded pair; then start after it
            found = False
            for i, r in enumerate(filtered):
                if (decoded_ca is None or r.get("created_at") == decoded_ca) and (decoded_id is None or r.get("id") == decoded_id):
                    start_index = i + 1
                    found = True
                    break
            if not found:
                # Not an error; empty results for cursor beyond dataset
                start_index = len(filtered)
        else:
            # Treat as raw id
            found = False
            for i, r in enumerate(filtered):
                if r.get("id") == cursor:
                    start_index = i + 1
                    found = True
                    break
            if not found:
                start_index = len(filtered)

    page = filtered[start_index:start_index + limit]

    # Next cursor if more results
    next_cursor = None
    has_more = start_index + limit < len(filtered)
    if has_more and page:
        last = page[-1]
        # Emit base64url cursor of "created_at|id" (opaque)
        ca = last.get("created_at") if isinstance(last.get("created_at"), str) else ""
        sid = last.get("id") if isinstance(last.get("id"), str) else ""
        payload = f"{ca}|{sid}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    resp = {
        "servers": page,
        "total": len(filtered),
        "limit": limit,
        "has_more": bool(has_more),
        "next_cursor": next_cursor
    }
    _record_log("ok")
    return resp

