    if base_url is not None:
        if not isinstance(base_url, str) or not base_url.startswith("http"):
            _log(endpoint, "error", server_id=server_id, details={"field": "base_url"})
            return _err("VALIDATION_ERROR", "base_url must start with 'http'.", field="base_url")

    if default_fetch_limit is not None:
        if not isinstance(default_fetch_limit, int) or isinstance(default_fetch_limit, bool):
            _log(endpoint, "error", server_id=server_id, details={"field": "default_fetch_limit"})
            return _err("VALIDATION_ERROR", "default_fetch_limit must be an integer.", field="default_fetch_limit")
        if default_fetch_limit < 1 or default_fetch_limit > 500:
            _log(endpoint, "error", server_id=server_id, details={"field": "default_fetch_limit"})
            return _err("VALIDATION_ERROR", "default_fetch_limit must be between 1 and 500.", field="default_fetch_limit")

    allowed_status = ["provisioning", "active", "paused", "degraded", "deleted"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(endpoint, "error", server_id=server_id, details={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status value.", field="status")

    servers = _load("servers.json")
    subs = _load("topic_subscriptions.json")
    cached = _load("cached_messages.json")
    runs = _load("ingest_runs.json")

    srv = next((s for s in servers if s.get("id") == server_id), None)
    if not srv:
        _log(endpoint, "error", server_id=server_id)
        return _err("NOT_FOUND", "Server not found.", server_id=server_id)

    # Uniqueness: display_name unique
    if display_name is not None:
        dn = display_name.strip()
        if dn == "":
            _log(endpoint, "error", server_id=server_id, details={"field": "display_name"})
            return _err("VALIDATION_ERROR", "display_name must not be empty.", field="display_name")
        conflict = next((s for s in servers if s.get("display_name") == dn and s.get("id") != server_id), None)
        if conflict:
            _log(endpoint, "error", server_id=server_id, details={"field": "display_name"})
            return _err("CONFLICT", "display_name must be unique.", field="display_name")

    # Lifecycle transitions
    transitions = {
        "provisioning": ["active", "degraded", "deleted"],
        "active": ["paused", "degraded", "deleted"],
        "paused": ["active", "deleted"],
        "degraded": ["active", "paused", "deleted"],
        "deleted": [],
    }
    current_status = srv.get("status")
    if current_status not in transitions:
        _log(endpoint, "error", server_id=server_id)
        return _err("VALIDATION_ERROR", "Server has invalid stored status.", field="status")

    # Apply updates
    changed = False
    now = _now()

    if display_name is not None:
        dn = display_name.strip()
        if srv.get("display_name") != dn:
            srv["display_name"] = dn
            changed = True

    if base_url is not None:
        if srv.get("base_url") != base_url:
            srv["base_url"] = base_url
            changed = True

    if default_fetch_limit is not None:
        if srv.get("default_fetch_limit") != default_fetch_limit:
            srv["default_fetch_limit"] = default_fetch_limit
            changed = True

    if status is not None and status != current_status:
        if status not in transitions.get(current_status, []):
            _log(endpoint, "error", server_id=server_id, details={"from": current_status, "to": status})
            return _err("INVALID_TRANSITION", "Invalid server status transition.", from_status=current_status, to_status=status)

        # Business rule: active only after at least one active subscription exists
        if status == "active":
            has_active_sub = any(
                (r.get("server_id") == server_id and r.get("status") == "active")
                for r in subs
            )
            if not has_active_sub:
                _log(endpoint, "error", server_id=server_id, details={"rule": "server_active_requires_active_subscription"})
                return _err("CONFLICT", "Cannot set server to active without at least one active subscription.")

        # Cascade on delete
        if status == "deleted":
            # mark subscriptions deleted
            for r in subs:
                if r.get("server_id") == server_id and r.get("status") != "deleted":
                    # valid transitions active/paused -> deleted; deleted terminal
                    if r.get("status") in ("active", "paused"):
                        r["status"] = "deleted"
                        r["updated_at"] = now
                    else:
                        r["status"] = "deleted"
                        r["updated_at"] = now
            # mark cached messages deleted
            for m in cached:
                if m.get("server_id") == server_id and m.get("status") != "deleted":
                    if m.get("status") in ("visible", "archived"):
                        m["status"] = "deleted"
                        m["updated_at"] = now
                    else:
                        m["status"] = "deleted"
                        m["updated_at"] = now
            # cancel running ingest runs
            for ir in runs:
                if ir.get("server_id") == server_id and ir.get("status") == "running":
                    ir["status"] = "cancelled"
                    ir["finished_at"] = now
                    ir["updated_at"] = now

            _save("topic_subscriptions.json", subs)
            _save("cached_messages.json", cached)
            _save("ingest_runs.json", runs)

        srv["status"] = status
        changed = True

    if not changed:
        _log(endpoint, "ok", server_id=server_id, resource_id=server_id, details={"idempotent": True})
        return {"server": srv}

    srv["updated_at"] = now
    _save("servers.json", servers)

    _log(endpoint, "ok", server_id=server_id, resource_id=server_id)
    return {"server": srv}

