            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, server_id=None, resource_id=None, details=None):
        fname_candidates = ["request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"]
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_code,
            "server_id": server_id,
            "resource_id": resource_id,
            "details": details or {},
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        }
        for fn in fname_candidates:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                data = _load(fn)
                if isinstance(data, list):
                    data.append(row)
                    _save(fn, data)
                break

    endpoint = "ntfy_me_subscriptions_create"

    if not isinstance(server_id, str) or not re.match(r"^ntfy_srv_[0-9A-Z]{18,}$", server_id):
        _log(endpoint, "error", server_id=server_id, details={"field": "server_id"})
        return _err("VALIDATION_ERROR", "Invalid server_id.", field="server_id")

    if not isinstance(subscriptions, list) or len(subscriptions) < 1:
        _log(endpoint, "error", server_id=server_id, details={"field": "subscriptions"})
        return _err("VALIDATION_ERROR", "subscriptions must be a non-empty array.", field="subscriptions")

    servers = _load("servers.json")
    subs = _load("topic_subscriptions.json")

    srv = next((s for s in servers if s.get("id") == server_id), None)
    if not srv:
        _log(endpoint, "error", server_id=server_id)
        return _err("NOT_FOUND", "Server not found.", server_id=server_id)

    if srv.get("status") == "deleted":
        _log(endpoint, "error", server_id=server_id)
        return _err("INVALID_TRANSITION", "Cannot create subscriptions for a deleted server.")

    transitions = {"active": ["paused", "deleted"], "paused": ["active", "deleted"], "deleted": []}
    allowed_status = ["active", "paused", "deleted"]

    created = []
    now = _now()

    # helper: generate ids with prefix and uppercase base32-ish chars
    _alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
    def _gen_id(prefix):
        # 18+ chars
        raw = uuid.uuid4().bytes + uuid.uuid4().bytes
        n = int.from_bytes(raw, "big")
        out = []
        while n > 0 and len(out) < 22:
            n, r = divmod(n, len(_alphabet))
            out.append(_alphabet[r])
        sfx = "".join(out)[:20].ljust(20, "A")
        return f"{prefix}_{sfx}"

    # Validate all first; also enforce unique(server_id, topic)
    seen_topics_in_request = set()
    for i, it in enumerate(subscriptions):
        if not isinstance(it, dict):
            _log(endpoint, "error", server_id=server_id, details={"index": i})
            return _err("VALIDATION_ERROR", "Each subscription must be an object.", index=i)

        if "topic" not in it:
            _log(endpoint, "error", server_id=server_id, details={"index": i, "field": "topic"})
            return _err("VALIDATION_ERROR", "Missing required field topic.", field="topic", index=i)

        topic = it.get("topic")
        if not isinstance(topic, str) or topic.strip() == "":
            _log(endpoint, "error", server_id=server_id, details={"index": i, "field": "topic"})
            return _err("VALIDATION_ERROR", "topic must be a non-empty string.", field="topic", index=i)
        topic = topic.strip()

        if topic in seen_topics_in_request:
            _log(endpoint, "error", server_id=server_id, details={"index": i, "field": "topic"})
            return _err("CONFLICT", "Duplicate topic in request.", field="topic", topic=topic)
        seen_topics_in_request.add(topic)

        st = it.get("status", "active")
        if st is None:
            st = "active"
        if not isinstance(st, str) or st not in allowed_status:
            _log(endpoint, "error", server_id=server_id, details={"index": i, "field": "status"})
            return _err("VALIDATION_ERROR", "Invalid subscription status.", field="status", index=i)

        # rule: cannot activate subscription unless server is active or degraded
        if st == "active" and srv.get("status") not in ("active", "degraded"):
            _log(endpoint, "error", server_id=server_id, details={"index": i, "rule": "activate_requires_server_active_or_degraded"})
            return _err("INVALID_TRANSITION", "Cannot create an active subscription when server is paused.", index=i)

        since_event_id = it.get("since_event_id")
        if since_event_id is not None and not isinstance(since_event_id, str):
            _log(endpoint, "error", server_id=server_id, details={"index": i, "field": "since_event_id"})
            return _err("VALIDATION_ERROR", "since_event_id must be a string.", field="since_event_id", index=i)

        dedupe_key = it.get("dedupe_key")
        if dedupe_key is not None and not isinstance(dedupe_key, str):
            _log(endpoint, "error", server_id=server_id, details={"index": i, "field": "dedupe_key"})
            return _err("VALIDATION_ERROR", "dedupe_key must be a string.", field="dedupe_key", index=i)

    # Create / idempotency
    for it in subscriptions:
        topic = it["topic"].strip()
        st = it.get("status", "active") or "active"
        since_event_id = it.get("since_event_id")
        dedupe_key = it.get("dedupe_key")

        # If exists by unique(server_id, topic), be idempotent and return it
        existing = next((r for r in subs if r.get("server_id") == server_id and r.get("topic") == topic), None)
        if existing and existing.get("status") != "deleted":
            created.append(existing)
            continue

        # If dedupe_key provided, treat as idempotency for (server_id, topic, dedupe_key)
        # We don't have a column for it; emulate by hashing into since_event_id only if since_event_id is None? No.
        # Instead, detect prior creates by matching a synthetic fingerprint in error-free way: search deleted too.
        if dedupe_key is not None:
            fp = hashlib.sha256(f"{server_id}|{topic}|{dedupe_key}".encode("utf-8")).hexdigest()
            prior = next((r for r in subs if r.get("server_id") == server_id and r.get("topic") == topic and r.get("idempotency_fingerprint") == fp), None)
            if prior:
                created.append(prior)
                continue
        else:
            fp = None

        # If existing is deleted, cannot recreate with same unique key unless we "revive" it.
        if existing and existing.get("status") == "deleted":
            # revive allowed only if transition deleted -> ? is not allowed by lifecycle, so create a new row is safer.
            # But unique(server_id, topic) would conflict; thus we revive by updating status if legal (it's not).
            _log(endpoint, "error", server_id=server_id, details={"topic": topic})
            return _err("CONFLICT", "Subscription with this topic already exists and is deleted; cannot recreate due to uniqueness constraint.", topic=topic)

        new_row = {
            "id": _gen_id("ntfy_sub"),
            "server_id": server_id,
            "topic": topic,
            "status": st,
            "since_event_id": since_event_id,
            "last_polled_at": None,
            "created_at": now,
            "updated_at": now,
        }
        if fp is not None:
            new_row["idempotency_fingerprint"] = fp  # extra field tolerated in JSON store

        subs.append(new_row)
        created.append(new_row)

    # No success without effect: if all were already existing, that's still an effect? It's idempotent, allowed.
    # But ensure at least one row matched/returned:
    if len(created) == 0:
        _log(endpoint, "error", server_id=server_id)
        return _err("NOT_FOUND", "No subscriptions created.")

    _save("topic_subscriptions.json", subs)

    # Business rule: server becomes active only after at least one active subscription exists
    if srv.get("status") in ("provisioning", "paused") and any(r.get("status") == "active" for r in created):
        # Only allow provisioning->active, paused->active
        transitions_srv = {
            "provisioning": ["active", "degraded", "deleted"],
            "active": ["paused", "degraded", "deleted"],
            "paused": ["active", "deleted"],
            "degraded": ["active", "paused", "deleted"],
            "deleted": [],
        }
        cur = srv.get("status")
        if "active" in transitions_srv.get(cur, []):
            srv["status"] = "active"
            srv["updated_at"] = now
            _save("servers.json", servers)

    _log(endpoint, "ok", server_id=server_id, resource_id=server_id, details={"created_or_returned": len(created)})
    return {"subscriptions": created}

