    import json, os, datetime, time, re, uuid

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0302000" if __import__("os").path.isdir("./environment_mix/0302000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, server_id=None, resource_id=None, details=None):
        fname_candidates = ["request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"]
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_code,
            "server_id": server_id,
            "resource_id": resource_id,
            "details": details or {},
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        }
        for fn in fname_candidates:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                data = _load(fn)
                if isinstance(data, list):
                    data.append(row)
                    _save(fn, data)
                break

    endpoint = "ntfy_me_subscriptions_update"

    if not isinstance(subscription_id, str) or not re.match(r"^ntfy_sub_[0-9A-Z]{18,}$", subscription_id):
        _log(endpoint, "error", details={"field": "subscription_id"})
        return _err("VALIDATION_ERROR", "Invalid subscription_id.", field="subscription_id")

    if topic is not None:
        if not isinstance(topic, str) or topic.strip() == "":
            _log(endpoint, "error", details={"field": "topic"})
            return _err("VALIDATION_ERROR", "topic must be a non-empty string.", field="topic")

    allowed_status = ["active", "paused", "deleted"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(endpoint, "error", details={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status value.", field="status")

    if since_event_id is not None and not isinstance(since_event_id, str):
        _log(endpoint, "error", details={"field": "since_event_id"})
        return _err("VALIDATION_ERROR", "since_event_id must be a string.", field="since_event_id")

    subs = _load("topic_subscriptions.json")
    servers = _load("servers.json")

    sub = next((r for r in subs if r.get("id") == subscription_id), None)
    if not sub:
        _log(endpoint, "error", resource_id=subscription_id)
        return _err("NOT_FOUND", "Subscription not found.", subscription_id=subscription_id)

    server_id = sub.get("server_id")
    srv = next((s for s in servers if s.get("id") == server_id), None)
    if not srv:
        _log(endpoint, "error", server_id=server_id, resource_id=subscription_id)
        return _err("NOT_FOUND", "Parent server not found.", server_id=server_id)

    transitions = {"active": ["paused", "deleted"], "paused": ["active", "deleted"], "deleted": []}
    cur_status = sub.get("status")
    if cur_status not in transitions:
        _log(endpoint, "error", server_id=server_id, resource_id=subscription_id)
        return _err("VALIDATION_ERROR", "Subscription has invalid stored status.", field="status")

    now = _now()
    changed = False

    if topic is not None:
        new_topic = topic.strip()
        # unique(server_id, topic)
        conflict = next((r for r in subs if r.get("server_id") == server_id and r.get("topic") == new_topic and r.get("id") != subscription_id), None)
        if conflict:
            _log(endpoint, "error", server_id=server_id, resource_id=subscription_id, details={"field": "topic"})
            return _err("CONFLICT", "Subscription topic must be unique per server.", field="topic")
        if sub.get("topic") != new_topic:
            sub["topic"] = new_topic
            changed = True

    if since_event_id is not None:
        if sub.get("since_event_id") != since_event_id:
            sub["since_event_id"] = since_event_id
            changed = True

    if status is not None and status != cur_status:
        if status not in transitions.get(cur_status, []):
            _log(endpoint, "error", server_id=server_id, resource_id=subscription_id, details={"from": cur_status, "to": status})
            return _err("INVALID_TRANSITION", "Invalid subscription status transition.", from_status=cur_status, to_status=status)

        # rule: cannot activate subscription unless parent server is active or degraded
        if status == "active" and srv.get("status") not in ("active", "degraded"):
            _log(endpoint, "error", server_id=server_id, resource_id=subscription_id, details={"rule": "activate_requires_server_active_or_degraded"})
            return _err("INVALID_TRANSITION", "Cannot activate subscription when parent server is paused or deleted.")

        sub["status"] = status
        changed = True

    if not changed:
        _log(endpoint, "ok", server_id=server_id, resource_id=subscription_id, details={"idempotent": True})
        return {"subscription": sub}

    sub["updated_at"] = now
    _save("topic_subscriptions.json", subs)

    _log(endpoint, "ok", server_id=server_id, resource_id=subscription_id)
    return {"subscription": sub}
